//! Same scheduler/authority/history/F2, with two real synthetic HTTP rounds.
use super::*;
fn capture(s:&Setup,g:&Record)->crate::pet_runtime::continuation::Captured{
 current_store(s).prepare_continuation_review(&s.f.path.join("authority"),&g.id,&g.spec.owner.pet_id,&g.revision,crate::assistant_memory::now(),false).unwrap().unwrap().1
}
fn next_review(s:&Setup,g:&Record,r:&crate::pet_runtime::messages::Receipt,server:&crate::local_chat::Server)->GoalReview{
 let at=crate::assistant_memory::now();GoalReview::prepare_continuation(g,evidence(s,g,server,at),caps(r),None,&s.config,capture(s,g),nonce().unwrap(),nonce().unwrap(),at).unwrap()
}
fn approve_next(s:&Setup,g:&Record,r:&crate::pet_runtime::messages::Receipt,server:&crate::local_chat::Server)->crate::pet_runtime::admission::Approved{
 let review=next_review(s,g,r,server);assert_eq!(review.proposal().continuation.as_ref().unwrap().schema_version,6);assert!(!review.proposal().continuation.as_ref().unwrap().additional_allowance);
 review.approve_with_data(g,evidence(s,g,server,crate::assistant_memory::now()),Some(GoalConsent::BoundedGoalContext),crate::assistant_memory::now()).unwrap()
}
fn execute(s:&Setup,q:&Record,server:&crate::local_chat::Server)->Record{
 let(_,o)=own(s,q,server);let driver=Driver::new(o.clone(),Arc::new(current_store(s)),environment(s,server)).unwrap();assert!(!driver.context_retirable());let result=run(driver.run());if !result.as_ref().is_ok_and(|s|s.phase==Phase::AwaitingVerification){retain_unexpected_driver(s,q,&driver,"finite-continuation");}let status=result.unwrap_or_else(|e|panic!("finite response driver: {e:?}; {:?}",driver.status()));assert_eq!(status.phase,Phase::AwaitingVerification,"{status:?}");assert!(driver.context_retirable());assert_eq!(o.workers(),0);assert!(s.main.runtime_resources().busy().unwrap().is_empty());current_store(s).read(&q.id,&q.spec.owner.pet_id).unwrap()
}
fn latest_body(s:&Setup,g:&Record)->Value{serde_json::from_slice::<Value>(&fs::read(s.f.path.join("authority").join(format!("{}.json",g.admissions.last().unwrap().spec.decision_id))).unwrap()).unwrap()["body"].clone()}
#[test]fn finite_continuation_uses_one_original_allowance_across_both_protocols_restart_and_reconciliation(){
 for provider in["ollama","lmstudio"]{
  let meta=if provider=="ollama"{metadata()}else{lm_metadata()};let(mut server,http)=http_fixture(vec![("application/json",meta.to_string()),("text/event-stream",stream("First bounded artefact",true)),("application/json",meta.to_string()),("text/event-stream",stream("Second bounded artefact",true))],|_|{});server.id=provider;
  let s=Setup::new();let(p,g,r)=draft_allowance(&s,if provider=="ollama"{"ai_ollama"}else{"ai_lmstudio"},true,Allowance{model_calls:2,tool_calls:1,output_bytes:8192});let q=queue(&s,&g,&r,&server);let first=execute(&s,&q,&server);let first_bytes=s.bytes(&first);
  let review=next_review(&s,&first,&r,&server);assert_eq!(review.proposal().continuation.as_ref().unwrap().charge.model_calls,1);assert_eq!(review.approve(&first,evidence(&s,&first,&server,crate::assistant_memory::now()),crate::assistant_memory::now()).err(),Some(Denial::DataConsentRequired));
  let approved=approve_next(&s,&first,&r,&server);assert_eq!(approved.spec().schema_version,13);assert_eq!(approved.spec().funding.as_ref().unwrap().schema_version,2);let a=Authority::existing(&s.f.path.join("authority")).unwrap();let cert=a.certify(&approved,&first,crate::assistant_memory::now()).unwrap();let q=current_store(&s).enqueue_certified(&cert,crate::assistant_memory::now()).unwrap().record;assert_eq!(q.schema_version,31);assert_eq!(latest_body(&s,&q)["schemaVersion"],22);assert_eq!(latest_body(&s,&p)["schemaVersion"],23);
  let final_goal=execute(&s,&q,&server);assert_eq!(http.join().unwrap().len(),4);assert_eq!(s.bytes(&first),first_bytes);assert_eq!(final_goal.admissions.len(),2);assert_eq!(final_goal.state,State::Paused);assert!(final_goal.completion.is_none());assert_eq!(final_goal.spec.criteria,first.spec.criteria);
  let a=Authority::existing(&s.f.path.join("authority")).unwrap();let history=a.history(&final_goal,crate::assistant_memory::now()).unwrap();assert!(history.accounting_complete&&history.source_consistent);assert_eq!(history.cumulative_charge.as_ref().unwrap().model_calls,2);let at=crate::assistant_memory::now();let third=GoalReview::prepare_continuation(&final_goal,evidence(&s,&final_goal,&server,at),caps(&r),None,&s.config,capture(&s,&final_goal),nonce().unwrap(),nonce().unwrap(),at);assert_eq!(third.err(),Some(Denial::Budget));
  let settled=reconcile(&s,&p,&r);assert_eq!(settled.consumed.as_ref().unwrap().model_calls,2);assert_eq!(settled.unknown.unwrap(),Allowance::default());assert_eq!(settled.held.unwrap(),Allowance::default());assert!(current_store(&s).prepare_continuation_review(&s.f.path.join("authority"),&final_goal.id,&final_goal.spec.owner.pet_id,&final_goal.revision,crate::assistant_memory::now(),false).is_err());
 }
}
#[test]fn competing_successors_bind_once_and_cancel_settles_the_whole_prefix_without_refunding_it(){
 let(mut server,http)=http_fixture(vec![("application/json",metadata().to_string()),("text/event-stream",stream("Original result",true))],|_|{});server.id="ollama";let s=Setup::new();let(p,g,r)=draft_allowance(&s,"ai_ollama",true,Allowance{model_calls:2,tool_calls:1,output_bytes:8192});let q=queue(&s,&g,&r,&server);let first=execute(&s,&q,&server);assert_eq!(http.join().unwrap().len(),2);
 let a=approve_next(&s,&first,&r,&server);let b=approve_next(&s,&first,&r,&server);let ca=s.a.certify(&a,&first,crate::assistant_memory::now()).unwrap();assert!(s.a.certify(&b,&first,crate::assistant_memory::now()).is_err());let q=current_store(&s).enqueue_certified(&ca,crate::assistant_memory::now()).unwrap().record;
 let cancel=Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_branch(p.clone(),&p.admissions[0].spec.decision_id,&r.envelope().message_id,crate::pet_runtime::delegation::BranchAction::Cancel,crate::assistant_memory::now()).unwrap().confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap();assert_eq!(cancel.stop.unwrap().binding.decision_id,q.admissions.last().unwrap().spec.decision_id);assert_eq!(latest_body(&s,&p)["schemaVersion"],23);let v=reconcile(&s,&p,&r);assert_eq!(v.consumed.as_ref().unwrap().model_calls,1);assert_eq!(v.unknown.unwrap(),Allowance::default());assert_eq!(v.remaining.unwrap().model_calls,2);assert_eq!(latest_body(&s,&q)["phase"],"revoked");
}
#[test]fn changed_authenticated_prefix_after_review_refuses_successor_before_queue_or_model(){
 let(mut server,http)=http_fixture(vec![("application/json",metadata().to_string()),("text/event-stream",stream("First result",true))],|_|{});server.id="ollama";let s=Setup::new();let(_,g,r)=draft_allowance(&s,"ai_ollama",true,Allowance{model_calls:2,tool_calls:1,output_bytes:8192});let q=queue(&s,&g,&r,&server);let first=execute(&s,&q,&server);assert_eq!(http.join().unwrap().len(),2);let approved=approve_next(&s,&first,&r,&server);let row=&first.admissions[0];s.a.request_stop(&row.spec,row.proof.as_ref().unwrap(),crate::pet_runtime::leases::StopReason::Cancel,crate::assistant_memory::now()).unwrap();assert!(s.a.certify(&approved,&first,crate::assistant_memory::now()).is_err());assert_eq!(current_store(&s).read_control(&first.id,"ai_ollama").unwrap().admissions.len(),1);
}

#[test]fn uncertain_model_attempt_retains_its_charge_and_cannot_authorize_another_round(){
 let(mut server,http)=http_fixture(vec![("application/json",metadata().to_string()),("text/event-stream",stream("Incomplete uncertain response",false))],|_|{});server.id="ollama";let s=Setup::new();let(_,g,r)=draft_allowance(&s,"ai_ollama",true,Allowance{model_calls:2,tool_calls:1,output_bytes:8192});let q=queue(&s,&g,&r,&server);let(_,o)=own(&s,&q,&server);let driver=Driver::new(o.clone(),Arc::new(current_store(&s)),environment(&s,&server)).unwrap();assert_eq!(run(driver.run()).unwrap().phase,Phase::RecoveryRequired);assert_eq!(http.join().unwrap().len(),2);let g=current_store(&s).read(&g.id,"ai_ollama").unwrap();assert_eq!(g.state,State::Paused);let before=latest_body(&s,&g);assert_eq!(before["budgetUsage"]["attempts"][0]["phase"],"uncertain");assert_eq!(before["budgetUsage"]["attempts"][0]["outputReserved"],4096);let answer=current_store(&s).prepare_continuation_review(&s.f.path.join("authority"),&g.id,"ai_ollama",&g.revision,crate::assistant_memory::now(),false).unwrap();assert!(matches!(answer,Err(Denial::UnreconciledEffects)));assert_eq!(latest_body(&s,&g),before);assert_eq!(o.workers(),0);assert!(s.main.runtime_resources().busy().unwrap().is_empty());
}

#[test]fn signalled_or_inactive_owner_is_not_a_context_release_proof(){
 let s=Setup::new();let(_,g,r)=draft_allowance(&s,"ai_ollama",true,Allowance{model_calls:2,tool_calls:1,output_bytes:8192});let server=crate::local_chat::Server{id:"ollama",name:"No IO",url:"http://127.0.0.1:1".into(),key:None};let q=queue(&s,&g,&r,&server);let(_,o)=own(&s,&q,&server);let driver=Driver::new(o.clone(),Arc::new(current_store(&s)),environment(&s,&server)).unwrap();assert!(!driver.context_retirable());crate::pet_runtime::lease_controller::signal_stop(o.lease());assert!(!driver.context_retirable());assert_eq!(run(driver.run()).unwrap().phase,Phase::Stopped);assert!(driver.context_retirable());assert_eq!(o.workers(),0);assert!(s.main.runtime_resources().busy().unwrap().is_empty());
}

#[test]fn finite_successor_can_review_initial_start_without_renewing_the_original_delegation_allowance(){
 let(mut server,http)=http_fixture(vec![("application/json",metadata().to_string()),("text/event-stream",stream("First bounded artefact",true))],|_|{});server.id="ollama";let s=Setup::new();let(_,g,r)=draft_allowance(&s,"ai_ollama",true,Allowance{model_calls:2,tool_calls:1,output_bytes:8192});let q=queue(&s,&g,&r,&server);let first=execute(&s,&q,&server);assert_eq!(http.join().unwrap().len(),2);
 let review=next_review(&s,&first,&r,&server).with_start(Some(crate::pet_runtime::planning::Start::WhenAvailable)).unwrap();let proposal=review.proposal();assert_eq!(proposal.execution_start.as_ref().unwrap().scope,crate::pet_runtime::admission::StartScope::FiniteResponse);assert_eq!(proposal.continuation.as_ref().unwrap().charge.model_calls,1);assert!(!proposal.continuation.as_ref().unwrap().additional_allowance);
 let approved=review.approve_with_data(&first,evidence(&s,&first,&server,crate::assistant_memory::now()),Some(GoalConsent::BoundedGoalContext),crate::assistant_memory::now()).unwrap();assert_eq!(approved.spec().schema_version,13);let a=Authority::existing(&s.f.path.join("authority")).unwrap();let cert=a.certify(&approved,&first,crate::assistant_memory::now()).unwrap();let queued=current_store(&s).enqueue_certified(&cert,crate::assistant_memory::now()).unwrap().record;assert_eq!(queued.schema_version,46);assert!(queued.admissions.last().unwrap().spec.execution_requested());
 let ack=current_store(&s).acknowledge_requested(&queued.id,"ai_ollama",&queued.revision,crate::assistant_memory::now()).unwrap();assert_eq!(ack.admissions.len(),2);assert!(ack.admissions.last().unwrap().lease.is_none());assert_eq!(ack.admissions.last().unwrap().spec.funding,queued.admissions.last().unwrap().spec.funding);assert_eq!(ack.admissions.last().unwrap().spec.budget,queued.admissions.last().unwrap().spec.budget);
}
